{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Bambuterol, a dimethylcarbamate ester, has an absolute oral bioavailability of about 10% in healthy adults, supporting low F for the query's carbamate-containing structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Physostigmine, a carbamate cholinesterase inhibitor, exhibits poor oral bioavailability in humans, supporting low F for the query's carbamate and ionizable nitrogen features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Agomelatine has an absolute oral bioavailability below 5% in humans, demonstrating that small molecules can have very low systemic F despite favorable absorption, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "BMS-187745 has an absolute oral bioavailability of 2.6% in healthy subjects, providing high-transfer evidence that low F is common even for small, soluble molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Apocynin has poor oral bioavailability (<10%) in humans, further supporting the low-F prediction for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a quaternary ammonium pyridinium carbamate with a permanent positive charge, which strongly impairs passive permeability and oral absorption. All transferred experimental evidence, including carbamate-containing analogues and other small molecules with high assay-transfer scores, consistently shows low oral bioavailability. The physicochemical prior and the experimental evidence align, supporting a low F (<20%) prediction.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "No evidence on whether the query is a substrate for active uptake transporters that could improve absorption.",
    "First-pass metabolism and intestinal stability of the quaternary carbamate are not directly characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

